scene.add(new THREE.HemisphereLight(0x9bdcff,0x151426,2.1));const key=new THREE.DirectionalLight(0xc3eeff,3.2);key.position.set(-4,9,7);key.castShadow=true;key.shadow.mapSize.set(1024,1024);key.shadow.camera.left=-8;key.shadow.camera.right=8;key.shadow.camera.top=8;key.shadow.camera.bottom=-8;scene.add(key);
