const mat=(color,metalness=0,roughness=.55,emissive=0,ei=0)=>new THREE.MeshStandardMaterial({color,metalness,roughness,emissive,emissiveIntensity:ei});
const concrete=mat(0x152635,.55,.42),dark=mat(0x07111c,.65,.36),steel=mat(0x718493,.8,.27),neonC=mat(0x16dff4,.2,.24,0x09dafa,3),neonP=mat(0xff3475,.2,.25,0xff1558,2.7),neonGold=mat(0xffb647,.4,.32,0xff7b19,1.8);
// Rooftop fighting platform
const floor=new THREE.Mesh(new THREE.CylinderGeometry(7.5,7.5,.42,64),concrete);floor.position.y=-.23;floor.receiveShadow=true;scene.add(floor);
const disc=new THREE.Mesh(new THREE.CylinderGeometry(5.1,5.1,.035,64),mat(0x102332,.48,.55));disc.position.y=-.005;disc.receiveShadow=true;scene.add(disc);
for(let r=4.2;r<=6.45;r+=2.2){const ring=new THREE.Mesh(new THREE.TorusGeometry(r,.025,8,96),r<5?neonC:neonP);ring.rotation.x=Math.PI/2;ring.position.y=.025;scene.add(ring)}
for(let i=0;i<32;i++){const a=i/32*Math.PI*2;const post=new THREE.Mesh(new THREE.BoxGeometry(.16,.42,.16),i%2?neonC:neonP);post.position.set(Math.cos(a)*6.8,.02,Math.sin(a)*6.8);scene.add(post)}
const grid=new THREE.GridHelper(34,34,0x1b4155,0x173044);grid.position.y=-.44;grid.material.transparent=true;grid.material.opacity=.34;scene.add(grid);
// Rooftop edge fins and glowing guardrails
for(const side of [-1,1]){for(let i=0;i<9;i++){let z=-6+i*1.5;const beam=new THREE.Mesh(new THREE.BoxGeometry(.1,2.8,.16),dark);beam.position.set(side*7.8,1.05,z);beam.castShadow=true;scene.add(beam)}for(let y of [.35,1.55]){const rail=new THREE.Mesh(new THREE.BoxGeometry(.12,.08,13.2),side<0?neonC:neonP);rail.position.set(side*7.8,y,-.1);scene.add(rail)}}
// Distant harbor skyline
for(let i=0;i<34;i++){const side=i%2?1:-1;const x=side*(8+Math.random()*18);const z=-10-Math.random()*19;const w=1.2+Math.random()*2.5,h=3+Math.random()*12;const b=new THREE.Mesh(new THREE.BoxGeometry(w,h,1.1+Math.random()*2),mat(i%3?0x101f31:0x152538,.35,.72));b.position.set(x,h/2-1.6,z);scene.add(b);if(i%2===0){for(let y=-.8;y<h-1;y+=.8){const win=new THREE.Mesh(new THREE.BoxGeometry(.025,.055,w*.58),i%4?neonC:neonP);win.position.set(x,y,z+.58);scene.add(win)}}}
// Signboards in the haze
function sign(x,y,z,color,text){const g=new THREE.Group();g.position.set(x,y,z);scene.add(g);let plate=new THREE.Mesh(new THREE.BoxGeometry(2.5,.72,.12),dark);g.add(plate);let frame=new THREE.Mesh(new THREE.BoxGeometry(2.62,.82,.08),color);frame.position.z=-.08;g.add(frame);plate.position.z=.01;const canvas=document.createElement('canvas');canvas.width=512;canvas.height=128;const ctx=canvas.getContext('2d');ctx.fillStyle='#06121d';ctx.fillRect(0,0,512,128);ctx.font='bold 70px sans-serif';ctx.textAlign='center';ctx.fillStyle='#d9fbff';ctx.shadowColor='#22dfff';ctx.shadowBlur=22;ctx.fillText(text,256,89);const tex=new THREE.CanvasTexture(canvas);const face=new THREE.Mesh(new THREE.PlaneGeometry(2.42,.61),new THREE.MeshBasicMaterial({map:tex,transparent:true}));face.position.z=.09;g.add(face);return g}
sign(-5.4,4.1,-5,neonC,'NIGHT CITY');sign(5.6,3.7,-5,neonP,'RISE / FIGHT');
// Atmosphere: stars, sparks, falling rain streaks
const starsGeo=new THREE.BufferGeometry(),starPos=[];for(let i=0;i<380;i++)starPos.push((Math.random()-.5)*60,Math.random()*17-1,-12-Math.random()*30);starsGeo.setAttribute('position',new THREE.Float32BufferAttribute(starPos,3));scene.add(new THREE.Points(starsGeo,new THREE.PointsMaterial({color:0x9bd9ff,size:.045,transparent:true,opacity:.75})));
const rainGeo=new THREE.BufferGeometry(),rainPos=new Float32Array(500*3);for(let i=0;i<500;i++){rainPos[i*3]=(Math.random()-.5)*26;rainPos[i*3+1]=Math.random()*12;rainPos[i*3+2]=(Math.random()-.5)*18-2}rainGeo.setAttribute('position',new THREE.BufferAttribute(rainPos,3));const rain=new THREE.Points(rainGeo,new THREE.PointsMaterial({color:0x6bbbe1,size:.025,transparent:true,opacity:.3}));scene.add(rain);

function capsule(parent,r,len,material,pos){const mesh=new THREE.Mesh(new THREE.CapsuleGeometry(r,len,4,8),material);mesh.position.copy(pos);mesh.castShadow=true;parent.add(mesh);return mesh}
function sphere(parent,r,material,pos,scale){const mesh=new THREE.Mesh(new THREE.SphereGeometry(r,16,12),material);mesh.position.copy(pos);if(scale)mesh.scale.set(...scale);mesh.castShadow=true;parent.add(mesh);return mesh}
function makeFighter(name,red=false){const root=new THREE.Group();scene.add(root);const rig=new THREE.Group();root.add(rig);
 const cloth=mat(red?0x271522:0x102536,.4,.4),armor=mat(red?0x751f3b:0x197084,.72,.27,red?0x330719:0x07303a,.45),skin=mat(red?0xa86652:0xc99273,.18,.48),glow=red?neonP:neonC,black=mat(0x080d16,.52,.33),gold=mat(red?0xffa64f:0x8cfff9,.7,.25,red?0xa64512:0x087d87,.6);
 // torso, pelvis, neck, head and sculpted mask
 const torso=capsule(rig,.34,.54,cloth,new THREE.Vector3(0,1.39,0));torso.rotation.z=Math.PI/2;
 const chest=new THREE.Mesh(new THREE.BoxGeometry(.48,.44,.47),armor);chest.position.set(.03,1.47,0);chest.castShadow=true;rig.add(chest);
 const pelvis=new THREE.Mesh(new THREE.BoxGeometry(.39,.27,.39),black);pelvis.position.set(0,1.07,0);pelvis.castShadow=true;rig.add(pelvis);
 capsule(rig,.13,.14,skin,new THREE.Vector3(0,1.78,0));const head=new THREE.Group();head.position.set(.01,2.02,0);rig.add(head);sphere(head,.24,skin,new THREE.Vector3(0,0,0),[.82,1.08,.82]);
 const mask=new THREE.Mesh(new THREE.BoxGeometry(.24,.13,.39),armor);mask.position.set(.16,-.02,0);head.add(mask);const visor=new THREE.Mesh(new THREE.BoxGeometry(.09,.065,.37),glow);visor.position.set(.215,.045,0);head.add(visor);
 // swept-back hair / hood fins
 const hood=new THREE.Mesh(new THREE.ConeGeometry(.25,.55,5),black);hood.rotation.z=-Math.PI/2;hood.position.set(-.23,.12,0);head.add(hood);const crest=new THREE.Mesh(new THREE.BoxGeometry(.36,.055,.12),glow);crest.position.set(-.09,.22,-.02);crest.rotation.z=-.15;head.add(crest);
 // shoulder plates
 for(const z of [-.29,.29]){const sh=sphere(rig,.2,armor,new THREE.Vector3(.01,1.63,z),[1.05,.82,1]);const spike=new THREE.Mesh(new THREE.ConeGeometry(.095,.28,5),gold);spike.position.set(-.05,1.82,z);spike.rotation.z=-.38;rig.add(spike)}
 const limbs={};function limb(keyName,upperLen,lowerLen,z,arm=true){const pivot=new THREE.Group();pivot.position.set(0,arm?1.57:.99,z);rig.add(pivot);let r=arm?.115:.16;capsule(pivot,r,upperLen,cloth,new THREE.Vector3(0,-upperLen/2-.025,0));const joint=new THREE.Group();joint.position.y=-upperLen-.02;pivot.add(joint);sphere(joint,r*.9,armor,new THREE.Vector3(0,0,0));capsule(joint,r*.83,lowerLen,armor,new THREE.Vector3(0,-lowerLen/2,0));if(arm){const fist=sphere(joint,.145,black,new THREE.Vector3(.035,-lowerLen-.035,0),[1,.9,.95]);const band=new THREE.Mesh(new THREE.CylinderGeometry(.13,.13,.11,12),glow);band.rotation.z=Math.PI/2;band.position.set(.03,-lowerLen*.65,0);joint.add(band)}else{const boot=new THREE.Mesh(new THREE.BoxGeometry(.37,.2,.29),black);boot.position.set(.11,-lowerLen-.06,.02);joint.add(boot);const stripe=new THREE.Mesh(new THREE.BoxGeometry(.3,.045,.3),glow);stripe.position.set(.12,-lowerLen-.01,.02);joint.add(stripe)}limbs[keyName]={pivot,joint};}
 limb('armA',.34,.32,-.31,true);limb('armB',.34,.32,.31,true);limb('legA',.4,.42,-.18,false);limb('legB',.4,.42,.18,false);
 // emissive chest reactor and back ribbon
 const core=new THREE.Mesh(new THREE.OctahedronGeometry(.105,1),glow);core.position.set(.29,1.48,-.01);rig.add(core);const reactor=new THREE.Mesh(new THREE.TorusGeometry(.14,.025,7,24),gold);reactor.position.copy(core.position);reactor.rotation.y=Math.PI/2;rig.add(reactor);
 for(let s of [-1,1]){const fin=new THREE.Mesh(new THREE.BoxGeometry(.5,.045,.07),glow);fin.position.set(-.31,1.35,s*.14);fin.rotation.z=-.18;rig.add(fin)}
 root.userData={name,rig,limbs,core,red,health:100,attack:0,attackType:'',cool:0,stun:0,guard:false,flash:0,walk:0,combo:0,comboTime:0};root.scale.setScalar(1.05);return root}
const player=makeFighter('KAIRO'),enemy=makeFighter('VEX',true);player.position.set(-1.72,0,0);enemy.position.set(1.72,0,-.12);enemy.rotation.y=Math.PI;

