const player=makeFighter('KAIRO'),enemy=makeFighter('VEX',true);player.position.set(-1.72,0,0);enemy.position.set(1.72,0,-.12);enemy.rotation.y=Math.PI;
const ui={overlay:document.querySelector('#overlay'),play:document.querySelector('#play'),msg:document.querySelector('#message'),timer:document.querySelector('#timer'),combo:document.querySelector('#combo')};let playing=false,ended=false,remaining=90,playerCombo=0,gameClock=0,msgTimeout=0,shake=0;
const keys={};const joy={x:0,y:0};let soundOn=true,audio;
function announce(text,sub='',duration=1100){ui.msg.innerHTML=text+(sub?`<em>${sub}</em>`:'');ui.msg.classList.add('show');clearTimeout(msgTimeout);msgTimeout=setTimeout(()=>ui.msg.classList.remove('show'),duration)}
function startGame(){player.userData.health=100;enemy.userData.health=100;player.position.set(-1.72,0,0);enemy.position.set(1.72,0,-.12);remaining=90;playerCombo=0;ended=false;playing=true;ui.overlay.classList.add('hidden');document.querySelector('#p-health').style.width='100%';document.querySelector('#e-health').style.width='100%';document.querySelector('#p-hp').textContent='100';document.querySelector('#e-hp').textContent='100';ui.timer.innerHTML='90<small>ROUND TIME</small>';ui.combo.style.display='none';announce('FIGHT!','FIRST TO FALL',1200)}
ui.play.addEventListener('click',startGame);
function playTone(freq=180,type='sawtooth',duration=.09,volume=.05){if(!soundOn)return;try{audio??=new AudioContext();if(audio.state==='suspended')audio.resume();const o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.setValueAtTime(freq,audio.currentTime);o.frequency.exponentialRampToValueAtTime(Math.max(45,freq*.55),audio.currentTime+duration);g.gain.setValueAtTime(volume,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+duration)}catch{}}
document.querySelector('#sound').onclick=e=>{soundOn=!soundOn;e.currentTarget.textContent=soundOn?'♪':'×';if(soundOn)playTone(480,'sine',.08,.025)};
function attack(f,type){if(!playing||f.userData.stun>0||f.userData.cool>0||f.userData.attack>0)return;const d=f.userData;d.attackType=type;d.attack=type==='special'?.62:type==='kick'?.5:.38;d.attackHit=false;d.cool=type==='special'?1.05:type==='kick'?.5:.28;d.guard=false;playTone(type==='special'?290:type==='kick'?125:220,type==='special'?'sine':'sawtooth',.09,.035)}
function guard(f,on){if(playing&&f.userData.attack<=0)f.userData.guard=on}
window.addEventListener('keydown',e=>{const k=e.key.toLowerCase();keys[k]=true;if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();if(k==='j'||k==='z')attack(player,'punch');if(k==='k'||k==='x')attack(player,'kick');if(k==='l'||k==='c')attack(player,'special');if(k===' ')guard(player,true);if(k==='enter'&&!playing)startGame()});window.addEventListener('keyup',e=>{keys[e.key.toLowerCase()]=false;if(e.key===' ')guard(player,false)});
const stick=document.querySelector('#stick'),knob=document.querySelector('#knob');let stickId=null;stick.addEventListener('pointerdown',e=>{stickId=e.pointerId;stick.setPointerCapture(stickId);moveStick(e)});stick.addEventListener('pointermove',e=>{if(e.pointerId===stickId)moveStick(e)});function moveStick(e){const r=stick.getBoundingClientRect(),dx=e.clientX-(r.left+r.width/2),dy=e.clientY-(r.top+r.height/2),max=r.width*.34,len=Math.hypot(dx,dy),s=Math.min(1,max/Math.max(1,len));joy.x=dx*s/max;joy.y=dy*s/max;knob.style.left=`${50+joy.x*34}%`;knob.style.top=`${50+joy.y*34}%`}function resetStick(e){if(e.pointerId!==stickId)return;stickId=null;joy.x=joy.y=0;knob.style.left='50%';knob.style.top='50%'}stick.addEventListener('pointerup',resetStick);stick.addEventListener('pointercancel',resetStick);
document.querySelectorAll('.action').forEach(button=>{const type=button.dataset.action;button.addEventListener('pointerdown',e=>{e.preventDefault();button.setPointerCapture(e.pointerId);if(type==='guard')guard(player,true);else attack(player,type)});const release=()=>{if(type==='guard')guard(player,false)};button.addEventListener('pointerup',release);button.addEventListener('pointercancel',release)});
function showCombo(){ui.combo.style.display=playerCombo>1?'block':'none';ui.combo.innerHTML=`${playerCombo} HIT<small>COMBO</small>`}
const sparks=[];function burst(pos,color){const count=18,geo=new THREE.BufferGeometry(),arr=new Float32Array(count*3),vel=[];for(let i=0;i<count;i++){arr[i*3]=pos.x;arr[i*3+1]=pos.y;arr[i*3+2]=pos.z;vel.push(new THREE.Vector3((Math.random()-.5)*5,Math.random()*4,(Math.random()-.5)*4))}geo.setAttribute('position',new THREE.BufferAttribute(arr,3));const points=new THREE.Points(geo,new THREE.PointsMaterial({color,size:.1,transparent:true,opacity:1,blending:THREE.AdditiveBlending,depthWrite:false}));scene.add(points);sparks.push({points,vel,life:.42})}
function impact(attacker,target,type){const d=target.userData;if(d.guard){d.health=Math.max(0,d.health-(type==='special'?5:2));d.stun=.12;playTone(330,'triangle',.08,.04);burst(target.position.clone().add(new THREE.Vector3(0,1.3,0)),0x70efff)}else{const damage=type==='special'?17:type==='kick'?13:8;d.health=Math.max(0,d.health-damage);d.stun=type==='special'?.5:.25;d.guard=false;target.position.x+=attacker===player?.16:-.16;shake=.16;playTone(type==='special'?85:105,'square',.14,.055);burst(target.position.clone().add(new THREE.Vector3(0,1.25,0)),attacker===player?0x3ff4ff:0xff427e);if(attacker===player){if(player.userData.comboTime>0)playerCombo++;else playerCombo=1;player.userData.comboTime=1.3;showCombo();if(playerCombo>=3)announce(`${playerCombo} HIT COMBO`,'KEEP THE PRESSURE',650)}}}
function finish(){if(ended)return;ended=true;playing=false;const win=player.userData.health>enemy.userData.health;announce(win?'K.O.':'DEFEATED',win?'NEON HARBOR IS YOURS':'THE CITY REMEMBERS',1700);setTimeout(()=>{ui.overlay.classList.remove('hidden');document.querySelector('.eyebrow').textContent=win?'// CHAMPION OF NEON HARBOR':'// THE RIFT CLAIMS ANOTHER';document.querySelector('h1').innerHTML=win?'YOU\'RE THE<span>CHAMPION</span>':'THE<span>RIFT</span>';document.querySelector('.subtitle').textContent=win?'Neon Harbor belongs to you. But the night is far from over.':'Vex held the line this time. The rematch is yours to claim.';ui.play.innerHTML='FIGHT AGAIN <span>↗</span>'},1650)}

